function [re, ve] = gnss_ecef(c, w, r, v)
%GNSS_ECEF  The truth (r [m], v [m/s], J2000) in ECEF: r_e = C r and v_e = C (v - w x r) with C the truth's J2000 to ECEF at the fix's
%   epoch and w the Earth's rate in J2000 (the transport theorem, the frame turning about w).
%   c: real[1][3][3] (passed a plain number)
%   w: real[1/s][3] (passed in 1/s)
%   r: real[m][3] (passed in m)
%   v: real[m/s][3] (passed in m/s)
%   returns re: real[m][3] (passed in m)
%   returns ve: real[m/s][3] (passed in m/s)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    re = zeros(3, 1);
    ve = zeros(3, 1);
    re = [c(1, 1)*r(1) + c(1, 2)*r(2) + c(1, 3)*r(3); c(2, 1)*r(1) + c(2, 2)*r(2) + c(2, 3)*r(3); c(3, 1)*r(1) + c(3, 2)*r(2) + c(3, 3)*r(3)];
    h__707 = (v - [w(2)*r(3) - w(3)*r(2); w(3)*r(1) - w(1)*r(3); w(1)*r(2) - w(2)*r(1)]);
    ve = [c(1, 1)*h__707(1) + c(1, 2)*h__707(2) + c(1, 3)*h__707(3); c(2, 1)*h__707(1) + c(2, 2)*h__707(2) + c(2, 3)*h__707(3); c(3, 1)*h__707(1) + c(3, 2)*h__707(2) + c(3, 3)*h__707(3)];
end
